  "`kubectl create configmap notify-config --from-literal=SMTP_HOST=mail.lab.local --from-literal=SMTP_PORT=587` と `kubectl create secret generic notify-secret --from-literal=smtp-password=not-a-real-password`": "`kubectl create configmap notify-config --from-literal=SMTP_HOST=mail.lab.local --from-literal=SMTP_PORT=587` and `kubectl create secret generic notify-secret --from-literal=smtp-password=not-a-real-password`",
